use serde_json::json;
use symbolica::prelude::*;
use symbolica_amflow::{
    Error, FlowOptions, Precision, Result, RunContext,
    diffexp::{EpsilonBoundary, EpsilonSystem, transport_epsilon},
};
fn atom(s: &str) -> Atom {
    Atom::parse(s, "residual_alias_mre", Default::default()).unwrap()
}
fn main() -> Result<()> {
    let x = match atom("x").as_view() {
        AtomView::Var(v) => v.get_symbol(),
        _ => unreachable!(),
    };
    let g = atom("2*1001*1002*1003*x^1000*(x-1/2)*(x-1)");
    let primitive = atom("2*1001*1002*1003*(x^1003/1003-3*x^1002/(2*1002)+x^1001/(2*1001))");
    let derivative_proof = (&primitive.derivative(x) - &g).expand().is_zero();
    let exact_integral = primitive.replace(Atom::var(x)).with(1).expand();
    if !derivative_proof || exact_integral != atom("-999") {
        return Err(Error::InvalidInput("exact proof failed".into()));
    }
    let system = EpsilonSystem {
        variable: x,
        matrices: vec![vec![vec![atom("0")]], vec![vec![g.clone()]]],
    };
    let bdy = |p: Precision| {
        Ok(EpsilonBoundary {
            point: p.zero(),
            leading: 0,
            coefficients: vec![vec![p.i(1)], vec![p.zero()]],
        })
    };
    let context = RunContext::default();
    let mut runs = Vec::new();
    for (digits, order) in [(60, 16), (80, 48), (60, 80), (80, 112)] {
        let p = Precision::decimal(digits)?;
        let options = FlowOptions {
            digits: 20,
            guard_digits: digits - 20,
            series_order: order,
            max_steps: 100,
            ..Default::default()
        };
        let solution = system.compile(p, &Default::default())?.transport(
            &bdy(p)?,
            &[p.i(1)],
            &options,
            &context,
            true,
        )?;
        runs.push(json!({"working_digits":digits,"order":order,"coefficients":solution.coefficients.iter().map(|r|r.iter().map(|z|json!({"re":z.re.to_string(),"im":z.im.to_string()})).collect::<Vec<_>>()).collect::<Vec<_>>(),"verified_digits":solution.verified_digits,"segments":solution.segments.len(),"diagnostics":format!("{:?}",solution.diagnostics)}));
    }
    let options = FlowOptions {
        digits: 20,
        guard_digits: 40,
        series_order: 80,
        max_steps: 100,
        ..Default::default()
    };
    let solution = transport_epsilon(&system, bdy, &[atom("1")], &options, &context, true)?;
    let p = Precision::decimal(80)?;
    let error = p.norm(&p.sub(&solution.coefficients[1][0], &p.i(-999)));
    let record = json!({"counterexample":"y'=epsilon*g(x)*y, y(0)=1; epsilon orders zero and one", "g":g.to_canonical_string(),"N":1000,"antiderivative":primitive.to_canonical_string(),"exact_derivative_verified_by_symbolica":derivative_proof,"exact_integral":exact_integral.to_canonical_string(),"exact_endpoint_coefficients":["1","-999"],"raw_runs":runs,"public_verified_transport":{"verified_digits":solution.verified_digits,"epsilon1":solution.coefficients[1][0].re.to_string(),"epsilon1_absolute_error":error.to_string(),"comparison_errors":solution.comparison_errors.iter().map(|r|r.iter().map(ToString::to_string).collect::<Vec<_>>()).collect::<Vec<_>>(),"checkpoints":solution.checkpoints.len(),"diagnostics":format!("{:?}",solution.diagnostics)},"explanation":"All retained Taylor orders below N+1 miss g; endpoint and midpoint g vanish exactly, so all collocation defects and retained tail vanish. Independent order/precision reruns agree on an incorrect answer."});

    use std::collections::BTreeMap;
    use symbolica_amflow::{
        Prescription, RustFlow, kinematics::KinematicSystem, transport_cache::*,
    };
    let epsilon = match atom("eps").as_view() {
        AtomView::Var(v) => v.get_symbol(),
        _ => unreachable!(),
    };
    let flow = RustFlow::new(
        KinematicSystem {
            epsilon,
            derivatives: BTreeMap::from([(x, vec![vec![Atom::var(epsilon) * g]])]),
        },
        &[atom("I1")],
        &atom("1"),
        Prescription::PlusI0,
        "regular real path0to1",
    )?;
    let source = CachedBoundary {
        identity: flow.identity().clone(),
        point: CachedPoint::Exact(BTreeMap::from([(x, atom("1"))])),
        kind: PointKind::Physical,
        range: EpsilonRange::new(0, 1)?,
        coefficients: solution.coefficients.clone(),
        accuracy: BoundaryAccuracy::from_solution(
            &solution,
            80,
            "generated by archived e733 public transport_epsilon; known aliased false result retained solely for compatibility regression",
        )?,
    };
    let mut cache = RustFlowCache::default();
    cache.insert(source)?;
    let directory = std::path::Path::new("target/cache-verification-audit/e733-alias-snapshot");
    cache.save(directory)?;
    let mut loaded = RustFlowCache::load(directory)?;
    let policy = ScaledDistance {
        scales: BTreeMap::new(),
        admissible: |_: &CachedBoundary, _: &CachedPoint| Ok(true),
    };
    let hit = flow.evaluate_to(
        &mut loaded,
        &BTreeMap::from([(x, atom("1"))]),
        EpsilonRange::new(0, 1)?,
        &options,
        &context,
        &policy,
    )?;
    assert!(hit.transport.is_none());
    assert_eq!(hit.boundary.coefficients[1][0], p.zero());
    println!("{}",serde_json::to_string_pretty(&json!({"original_reproduction":record,"snapshot_directory":directory,"same_old_binary_exact_hit_returns_aliased_zero":true,"snapshot_identity":flow.identity().key()})).unwrap());

    if solution.verified_digits != Some(20) || !p.norm(&solution.coefficients[1][0]).is_zero() {
        return Err(Error::InvalidInput(
            "expected old-library failure mode not reproduced".into(),
        ));
    }
    Ok(())
}
